#!/usr/bin/env python3
"""Generate public bilingual documentation from one maintained content source."""
from pathlib import Path
import json,re
r=Path(__file__).resolve().parents[1];s=json.loads((r/'docs/content.json').read_text());repo='https://github.com/deckerweb/builder-shortcode-extras';wiki=repo+'/wiki/'
examples='''```text
[bse-copyright first="2019"]
[bse-post-date format="Y-m-d"]
[bse-post-modified-date label="Last updated: "]
[bse-post-link id="123" text="Read more"]
[bse-item-content id="123"]
```'''
for lang,d in s['languages'].items():
 de=lang=='de';other='en' if de else 'de';guide='Deutsch' if de else 'English';suffix='-de' if de else ''
 headings={'glance':'Auf einen Blick' if de else 'At a Glance','install':'Installation und erste Schritte' if de else 'Installation and first steps','features':'Helfer für den Alltag' if de else 'Everyday helpers','examples':'Beispiele' if de else 'Examples','updates':'Updates und Library' if de else 'Updates and Library','data':'Daten und Multisite' if de else 'Data and Multisite','faq':'FAQ','changelog':'Changelog','about':'Autor und Zweck' if de else 'Author and scope','support':'Support und Sicherheit' if de else 'Support and security','license':'Lizenz und Herkunft' if de else 'License and provenance'}
 def anchor(text):return re.sub(r'[^a-z0-9äöüß -]','',text.lower()).replace(' ','-')
 glance=['Durchsuchbare Shortcode-Hilfe direkt unter Werkzeuge → Builder Shortcode Extras.','Fünf Generatorfälle: Copyright, Veröffentlichungs-/Änderungsdatum, Beitragslink und Inhaltseinbettung.','Native Blöcke, synchronisierte Vorlagen und optionale Elementor-, Beaver-, Astra- und Genesis-Integrationen.','Lokale Ressourcen, deutsche Du-/Sie-Texte und WordPress-Updates über GitHub.'] if de else ['Searchable shortcode help under Tools → Builder Shortcode Extras.','Five generator cases: copyright, publication/modification date, post link and embedded content.','Native blocks, synced patterns and optional Elementor, Beaver, Astra and Genesis integrations.','Local assets, informal/formal German translations and WordPress updates from GitHub.']
 install='''1. Lade das Plugin-ZIP aus den GitHub-Releases herunter.
2. Öffne Plugins → Installieren → Plugin hochladen und aktiviere es.
3. Öffne Werkzeuge → Builder Shortcode Extras, wähle einen Helfer und kopiere den Shortcode.
4. Füge ihn in einen Shortcode-Block oder ein geeignetes Builder-Feld ein und prüfe die Ausgabe.

BSE speichert keine Generatorwerte und verändert keine Inhalte.''' if de else '''1. Download the plugin ZIP from GitHub Releases.
2. Open Plugins → Add New → Upload Plugin and activate it.
3. Open Tools → Builder Shortcode Extras, choose a helper and copy its shortcode.
4. Paste it into a Shortcode block or supported builder field and check its output.

BSE saves no generator values and changes no content.'''
 features='Copyright, Datumsangaben, Benutzerinformationen, Beitragslinks, Taxonomiebegriffe, Menüs und Kommentarformulare lassen sich gezielt einfügen. Viele Texthelfer unterstützen eigene CSS-Klassen und geprüfte HTML-Wrapper. Inhaltseinbettungen beachten Zugriffsrechte und unterbinden rekursive Verweise. Optionale Integrationen setzen den jeweiligen Builder beziehungsweise das Theme voraus.' if de else 'Insert copyright, dates, user information, post links, taxonomy terms, menus and comment forms where you need them. Most text helpers accept CSS classes and validated HTML wrappers. Content embedding respects access checks and prevents recursive references. Optional integrations require the corresponding builder or theme.'
 updates='Der deckerweb Updater 2.1.0 prüft stabile GitHub-Releases über die normale WordPress-Updateverwaltung. Er aktiviert keine automatischen Updates. Die eingebettete deckerweb Library 0.8.1 ergänzt einen optionalen Katalog unter Plugins → Installieren → deckerweb. Ihre Online-Katalogabfrage ist standardmäßig ausgeschaltet. Installation und Aktivierung sind getrennte Entscheidungen. GitHub sieht bei Metadaten- oder Paketabrufen die anfragende IP-Adresse; BSE übermittelt keine Nutzungsdaten, Website-Adresse oder Benutzerkennungen.' if de else 'The deckerweb Updater 2.1.0 checks stable GitHub releases through the normal WordPress update system. It does not enable automatic updates. Embedded deckerweb Library 0.8.1 adds an optional catalog under Plugins → Add New → deckerweb. Online catalog retrieval is off by default. Installation and activation are separate decisions. GitHub sees the requesting IP address for metadata/package requests; BSE sends no telemetry, site address or user identifiers.'
 data='BSE kann je Website oder netzwerkweit aktiviert werden. Inhalts-IDs gelten für die aktuelle Website. Website-Administratoren verwenden Werkzeuge → Builder Shortcode Extras; Super-Administratoren zusätzlich Netzwerkeinstellungen → Builder Shortcode Extras. Die Library-Optionen gelten je Netzwerk. BSE speichert keine Einstellungen. Deaktivierung erhält Daten; Deinstallation bereinigt den eigenen Updatecache. Library-Daten bleiben erhalten, solange ein weiterer Host installiert ist. Beim letzten Host werden temporäre Daten bereinigt; Optionen bleiben standardmäßig erhalten. Inhalte und installierte Plugins werden nicht gelöscht.' if de else 'Activate BSE per website or network-wide. Content IDs belong to the current website. Site administrators use Tools → Builder Shortcode Extras; super administrators also have Network Settings → Builder Shortcode Extras. Library preferences are shared per network. BSE saves no settings. Deactivation preserves data; uninstall removes its update cache. Other installed hosts protect shared Library data. The final host clears temporary data and preserves preferences by default. Content and installed plugins are never removed.'
 # Exactly seven practical readme questions; full collection retains technical answers.
 short=d['faq'][:3]+[d['faq'][7],d['faq'][14],d['faq'][-3],d['faq'][-1]]
 about='David Decker – DECKERWEB entwickelt und veröffentlicht dieses Plugin seit 2019. Es konzentriert sich auf kleine dynamische Helfer und wird direkt über GitHub verteilt. Die Builder-Integrationen sind optional; eine allgemeine Zertifizierung kommerzieller Builder wird nicht behauptet.' if de else 'David Decker – DECKERWEB develops and publishes this plugin, first released in 2019. It focuses on small dynamic helpers and is distributed directly through GitHub. Builder integrations are optional; broad certification of commercial builders is not claimed.'
 support=f"[Issues]({repo}/issues) · [Discussions]({repo}/discussions) · [Security]({repo}/security/advisories/new)\n\n"+('Sicherheitslücken bitte vertraulich melden. [Meldeweg](SECURITY.md). Unterstützung: ' if de else 'Report vulnerabilities privately. [Reporting policy](SECURITY.md). Support the project: ')+ '[Ko-fi](https://ko-fi.com/deckerweb) · [Buy Me a Coffee](https://buymeacoffee.com/daveshine) · [PayPal](https://paypal.me/deckerweb).'
 license='© 2019–2026 David Decker – DECKERWEB. [GPL v2 or later](https://www.gnu.org/licenses/gpl-2.0.html).\n\n'+('Mitgelieferte deckerweb Library und Updater: David Decker – DECKERWEB, GPL-2.0-or-later. Die BSE-Grafiken sind originale Vektorarbeiten; es werden keine Schriftdateien mitgeliefert. WordPress- und Builder-Namen gehören ihren jeweiligen Rechteinhabern.' if de else 'Bundled deckerweb Library and Updater: David Decker – DECKERWEB, GPL-2.0-or-later. BSE artwork is original vector work; no font files are bundled. WordPress and builder names belong to their respective owners.')
 faqtext='\n\n'.join('### '+f['q']+'\n\n'+f['a'] for f in short)+'\n\n'+f"[{'Alle Fragen nach Themen' if de else 'Complete FAQ by topic'}]({wiki}{guide}#{'fragen-nach-themen' if de else 'faq-by-topic'})."
 sections=[(headings['glance'],'\n'.join('- '+x for x in glance)),(headings['install'],install),(headings['features'],features),(headings['examples'],examples),(headings['updates'],updates),(headings['data'],data),(headings['faq'],faqtext),('Screenshots',('![Hilfe und Shortcode-Generator](assets-github/shortcode-tools-de.png)' if de else '![Shortcode help and generator](assets-github/shortcode-tools-en.png)')),(headings['changelog'],d['changelog'].split('\n',1)[1].strip()),(headings['about'],about),(headings['support'],support),(headings['license'],license)]
 opening=f"# {d['title']}\n\n![{d['title']}](assets-github/banner{suffix}.png)\n\n**{d['slogan']}**\n\n{d['intro']}\n\nVersion **{s['version']}** · WordPress **{s['requires_wp']}+** · PHP **{s['requires_php']}+** · GPL-2.0-or-later\n\n"
 opening+=f"[{'English' if de else 'Deutsch'}](README{'' if de else '-de'}.md) · [{'Anleitung und FAQ' if de else 'Guide and FAQ'}]({wiki}{guide}) · [Download]({repo}/releases/latest)\n\n## {'Inhalt' if de else 'Contents'}\n\n"+'\n'.join(f'- [{h}](#{anchor(h)})' for h,b in sections)+'\n\n'
 readme=opening+'\n\n'.join('## '+h+'\n\n'+b for h,b in sections)+'\n'
 (r/f'README{suffix}.md').write_text(readme)
 # WordPress readme structure keeps required platform section markers.
 txt=f"=== Builder Shortcode Extras ===\nContributors: deckerweb\nTags: shortcodes, dynamic content, templates\nRequires at least: {s['requires_wp']}\nRequires PHP: {s['requires_php']}\nStable tag: {s['version']}\nLicense: GPLv2 or later\nLicense URI: https://www.gnu.org/licenses/gpl-2.0.html\n\n{d['slogan']}\n\n== Description ==\n\n{d['intro']}\n\n"+'\n\n'.join('= '+h+' =\n\n'+b for h,b in sections[:6])+ '\n\n== Installation ==\n\n'+install+'\n\n== Frequently Asked Questions ==\n\n'+re.sub(r'^### (.+)$',r'= \1 =',faqtext,flags=re.M)+'\n\n== Changelog ==\n\n'+re.sub(r'^## (.+)$',r'= \1 =',d['changelog'].split('\n',1)[1].strip(),flags=re.M)+'\n\n= '+headings['about']+' =\n\n'+about+'\n\n'+support+'\n\n'+license+'\n'
 txt=txt.replace('== Changelog ==','== Screenshots ==\n\n1. '+('Plugin-Seite mit Hilfe und Generator auf Englisch.' if de else 'Plugin page with help and generator in English.')+'\n2. '+('Plugin-Seite mit Hilfe und Generator auf Deutsch.' if de else 'Plugin page with help and generator in German.')+'\n\n== Changelog ==',1)
 (r/f'readme{suffix}.txt').write_text(txt)
 (r/'docs'/f'CHANGELOG{suffix}.md').write_text(d['changelog'])
 (r/'docs'/f'changelog{suffix}.txt').write_text('== Changelog ==\n\n'+re.sub(r'^## (.+)$',r'= \1 =',d['changelog'].split('\n',1)[1].strip(),flags=re.M).replace('- **','* ').replace(':**',':')+'\n')
 groups=[('Einrichtung' if de else 'Getting started',d['faq'][:5]),('Ausgabe und Integrationen' if de else 'Output and integrations',d['faq'][5:14]),('Updates, Daten und Sicherheit' if de else 'Updates, data and security',d['faq'][14:])]
 fullfaq='## '+('Fragen nach Themen' if de else 'FAQ by topic')+'\n\n'+'\n\n'.join('### '+h+'\n\n'+'\n\n'.join('#### '+f['q']+'\n\n'+f['a'] for f in entries) for h,entries in groups)
 guidebody=f"# {d['title']}\n\n[English]({wiki}English) · [Deutsch]({wiki}Deutsch)\n\n**{d['slogan']}**\n\n{d['intro']}\n\nVersion **{s['version']}** · WordPress **{s['requires_wp']}+** · PHP **{s['requires_php']}+**\n\n## {'Erste Schritte' if de else 'Quick start'}\n\n{install}\n\n## {headings['examples']}\n\n{examples}\n\n## {'Shortcode-Referenz' if de else 'Shortcode reference'}\n\n{d['reference']}\n\n{fullfaq}\n\n## {'Entwickler' if de else 'Developers'}\n\n```php\nadd_filter( 'bse/filter/shortcodes_in_admin', '__return_true' );\n```\n\n"+('Bestehende Filter unter `bse/filter/shortcode_defaults/*` und `bse/filter/shortcode/*` bleiben erhalten. PHP-Callbacks sind vertrauenswürdiger Entwicklercode und können HTML zurückgeben. Menüs verwenden einen sicheren Standard-Callback; eigene Callbacks werden nur durch PHP-Standardfilter konfiguriert.' if de else 'Existing `bse/filter/shortcode_defaults/*` and `bse/filter/shortcode/*` filters remain. PHP callbacks are trusted developer code and may return HTML. Menus use a safe default callback; custom callbacks are configured only through PHP defaults filters.')+'\n\n'+f"[Changelog]({wiki}CHANGELOG{'%E2%80%90de' if de else ''}) · [Security]({repo}/security/advisories/new)\n"
 guidebody=guidebody.replace('## '+headings['examples'],'## '+('Plugin-Seite' if de else 'Plugin page')+'\n\n!['+('Hilfe und Shortcode-Generator' if de else 'Shortcode help and generator')+'](../assets-github/shortcode-tools-'+lang+'.png)\n\n## '+headings['examples'],1)
 (r/'docs'/f'{guide}.md').write_text(guidebody);(r/'docs/wiki'/f'{guide}.md').write_text(guidebody.replace('../assets-github/',repo+'/raw/master/assets-github/'));(r/'docs/wiki'/f'CHANGELOG{suffix}.md').write_text(d['changelog'])
 # Public testing guide has factual scope, without internal operations or paths.
 (r/'docs'/f'TESTING{suffix}.md').write_text(('# Prüfungen und Kompatibilität' if de else '# Checks and compatibility')+'\n\n[English](TESTING.md) · [Deutsch](TESTING-de.md)\n\n'+('Die Helfer wurden unter WordPress 6.7, 7.1.2 und 7.1.3 mit PHP 8.4.5 geprüft: Datumsangaben, Inhaltseinbettung, Zugriffsschutz, Shortcode-Registrierung, Kopiergenerator, Update-Metadaten, Netzwerkaktivierung und Berechtigungen in einer echten Multisite. Kommerzielle Builder wurden über repräsentative Adapterfälle geprüft; lizenzierte Builder-/Theme-Installationen wurden nicht vollständig zertifiziert. PHP 8.0 ist die deklarierte Mindestversion, wurde in diesem Prüfstand aber nicht als echte Laufzeit ausgeführt. Unterstützte Integrationen sollten im vorgesehenen Website-Kontext getestet werden.' if de else 'Helpers were checked on WordPress 6.7, 7.1.2 and 7.1.3 with PHP 8.4.5: dates, content embedding, access controls, shortcode registration, the copy generator, update metadata, network activation and permissions in an actual multisite. Commercial builders were covered through representative adapter cases; licensed builder/theme installations were not fully certified. PHP 8.0 is the declared minimum but was not executed as a real runtime in this check. Test supported integrations in their intended website context.')+'\n')
 (r/'docs'/f'CONVENTIONS{suffix}.md').write_text(('# Versions- und Datenkonventionen' if de else '# Release and data conventions')+'\n\n[English](CONVENTIONS.md) · [Deutsch](CONVENTIONS-de.md)\n\n'+('Versionsnummern verwenden Haupt-, Neben- und Fixversion. Neue Funktionen erhöhen die Nebenversion; kompatible Korrekturen die Fixversion. Inkompatible Änderungen benötigen eine Hauptversion und klare Hinweise. Stabile GitHub-Tags tragen das Präfix v. WordPress installiert das Paket builder-shortcode-extras.zip. Generatorwerte bleiben nur im aktuellen Browserdokument. BSE speichert keine Einstellungen. Library-Optionen und Installationsvermerke liegen unter deckerweb_library_settings_v1 und deckerweb_library_installed_v1, je Website beziehungsweise Netzwerk. Temporäre Library-Caches und Aktionssperren sowie der repositorybezogene BSE-Updater-Cache werden ausschließlich im dokumentierten eigenen Umfang bereinigt. Daten anderer Plugins bleiben erhalten.' if de else 'Versions use major, minor and patch components. Features increase the minor version; compatible fixes increase the patch. Breaking changes require a major version and clear notices. Stable GitHub tags use a v prefix. WordPress installs builder-shortcode-extras.zip. Generator drafts live only in the current browser document. BSE stores no settings. Library preferences and install records use deckerweb_library_settings_v1 and deckerweb_library_installed_v1, per website or network. Temporary Library caches/action locks and the repository-specific BSE updater cache are removed only within their documented ownership. Foreign plugin data remains.')+'\n')
# Formal local guide uses the same maintained German source and neutral questions.
formal=(r/'docs/Deutsch.md').read_text()
for informal, polite in [
    ('findest du','finden Sie'),
    ('Gib eine ID','Geben Sie eine ID'),
    ('Lade das Plugin-ZIP','Laden Sie das Plugin-ZIP'),
    ('Öffne Plugins','Öffnen Sie Plugins'),
    ('Öffne Werkzeuge','Öffnen Sie Werkzeuge'),
    ('wähle einen Helfer','wählen Sie einen Helfer'),
    ('kopiere den Shortcode','kopieren Sie den Shortcode'),
    ('Füge ihn','Fügen Sie ihn'),
    ('prüfe die Ausgabe','prüfen Sie die Ausgabe'),
    ('Prüfe ID','Prüfen Sie ID'),
    ('Prüfe die tatsächliche Ausgabe','Prüfen Sie die tatsächliche Ausgabe'),
    ('Prüfe die Ausgabe','Prüfen Sie die Ausgabe'),
    ('Öffne den Inhalt','Öffnen Sie den Inhalt'),
    ('Verwende Security','Verwenden Sie Security'),
    ('Nenne Plugin-','Nennen Sie Plugin-'),
    ('Poste Sicherheitsdetails','Posten Sie Sicherheitsdetails'),
    ('Gib über Entwicklerfilter','Geben Sie über Entwicklerfilter'),
    ('installierst du','installieren Sie'),
    ('kannst du','können Sie'),
    ('deiner','Ihrer'), ('deinem','Ihrem'), ('deinen','Ihren'), ('deine','Ihre'),
]:formal=formal.replace(informal,polite)
(r/'docs/Deutsch-formal.md').write_text(formal)

(r/'docs/wiki/Home.md').write_text(f"# Builder Shortcode Extras\n\n![Builder Shortcode Extras]({repo}/raw/master/assets-github/banner.png)\n\n**Small dynamic helpers. Ready when you need them.**\n\nFind a helper, configure one of five use cases and copy it into your WordPress layout. Dates, copyright, links and reusable content without custom PHP.\n\n## English\n\n- [Guide and FAQ by topic]({wiki}English)\n- [Complete changelog]({wiki}CHANGELOG)\n\n![Builder Shortcode Extras]({repo}/raw/master/assets-github/banner-de.png)\n\n**Kleine dynamische Helfer. Schnell eingesetzt.**\n\nWähle einen Helfer, konfiguriere einen der fünf Generatorfälle und kopiere den Shortcode in dein WordPress-Layout. Datumsangaben, Copyright, Links und wiederverwendbare Inhalte ohne eigenes PHP.\n\n## Deutsch\n\n- [Anleitung und Fragen nach Themen]({wiki}Deutsch)\n- [Vollständiger Änderungsverlauf]({wiki}CHANGELOG%E2%80%90de)\n\n[Download]({repo}/releases/latest) · [Support]({repo}/issues) · [Security]({repo}/security/advisories/new)\n")
(r/'docs/wiki/_Sidebar.md').write_text(f"## Builder Shortcode Extras\n\n[Home]({wiki})\n\n### English\n\n- [Guide and FAQ by topic]({wiki}English)\n- [Changelog]({wiki}CHANGELOG)\n\n### Deutsch\n\n- [Anleitung und Fragen nach Themen]({wiki}Deutsch)\n- [Änderungsverlauf]({wiki}CHANGELOG%E2%80%90de)\n\n### Project / Projekt\n\n- [Download]({repo}/releases/latest)\n- [Support]({repo}/issues)\n- [Private security reporting]({repo}/security/advisories/new)\n")
(r/'SECURITY.md').write_text(f"# Security / Sicherheit\n\n## English\n\nReport vulnerabilities privately through [Security → Advisories → Report a vulnerability]({repo}/security/advisories/new) in this host repository, including issues in its bundled deckerweb Library or Updater. Include plugin/component versions, WordPress/PHP versions, a minimal reproduction and expected impact. Never include passwords, tokens or personal user data. Use public Issues for ordinary bugs, without vulnerability details. David Decker assesses reports and coordinates fixes and disclosure; no fixed response deadline is promised. Use the latest stable release.\n\n## Deutsch\n\nMelde Sicherheitslücken vertraulich über [Security → Advisories → Report a vulnerability]({repo}/security/advisories/new) in diesem Host-Repository, auch für die eingebettete deckerweb Library oder den Updater. Nenne Plugin-/Komponentenversionen, WordPress/PHP-Versionen, eine minimale Reproduktion und die erwarteten Auswirkungen. Gib keine Passwörter, Tokens oder personenbezogenen Benutzerdaten weiter. Normale Fehler gehören in öffentliche Issues, ohne Sicherheitsdetails. David Decker prüft Meldungen und stimmt Korrekturen und Offenlegung ab; es wird keine feste Reaktionsfrist versprochen. Verwende die aktuelle stabile Version.\n")
(r/'.github/FUNDING.yml').write_text('ko_fi: deckerweb\nbuy_me_a_coffee: daveshine\ncustom: https://paypal.me/deckerweb\n')
(r/'_config.yml').write_text('theme: jekyll-theme-cayman\ntitle: Builder Shortcode Extras\ndescription: Small dynamic helpers. Ready when you need them.\n')
css=r/'assets/css';css.mkdir(exist_ok=True);(css/'style.scss').write_text('---\n---\n\n@import "{{ site.theme }}";\n\n.page-header { background-color: #2b2251; background-image: linear-gradient(120deg, #102d3b, #2b2251); }\n.main-content h1, .main-content h2, .main-content h3, .main-content h4, .main-content h5, .main-content h6 { font-weight: 700; color: #2b2251; }\n')
print('Generated four readmes, bilingual guides/FAQ/changelogs/wiki/security, data policies and Pages styles.')
